package career.assistant.application.service;
import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.company.repository.CompanyRepository; import career.assistant.job.entity.Job; import org.junit.jupiter.api.Test; import org.springframework.mail.javamail.JavaMailSender; import java.time.OffsetDateTime; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ApplicationNotificationServiceTest {@Test void verifiedSuccessEmailIsSentOnce(){var apps=mock(ApplicationRepository.class);var companies=mock(CompanyRepository.class);var sender=mock(JavaMailSender.class);var service=new ApplicationNotificationService(apps,companies,sender,true,"sender@example.com","sahana.gowda2227@gmail.com");Job job=mock(Job.class);when(job.getTitle()).thenReturn("Engineer");when(job.getCompanyId()).thenReturn(UUID.randomUUID());Application a=new Application();a.setJob(job);a.setStatus(ApplicationStatus.AUTO_APPLIED);a.setConfirmationId("CONF-1");a.setSubmittedAt(OffsetDateTime.now());a.setResumeVersionId(UUID.randomUUID());assertTrue(service.sendVerifiedSuccessOnce(a,"95"));assertFalse(service.sendVerifiedSuccessOnce(a,"95"));verify(sender,times(1)).send(any(org.springframework.mail.SimpleMailMessage.class));}}
